left join lateral (select case when count(*) = 1 then min(a.id::text)::uuid end as id from activity a where a.tenant_id = x.tenant and a.band = 'K2' and regexp_replace(lower(a.name), '[^a-z0-9]+', '', 'g') = regexp_replace(lower(v.t), '[^a-z0-9]+', '', 'g')) act on true
on conflict do nothing;
